import 'package:spring_boot_starter_feign/spring_boot_starter_feign.dart';
import 'package:spring_boot_feign_example/src/app.spring.dart';

/// Every bean under `lib/src/` (generated by spring_core_dart_generator);
/// bin/main.dart's application imports it. Its file also holds the `log`
/// getters of the `@Log` classes here.
@ComponentScan()
final BeanModule appBeans = $appBeans;
